fn envelope_at(&self, revision: u64, body: &serde_json::Value) -> RemoteReply {
    let text = serde_json::json!({
        "epoch": self.epoch,
        "revision": revision,
        "body": body,
    });
    RemoteReply {
        status: 200,
        body: text.to_string().into_bytes(),
        authenticated: true,
    }
}

fn envelope(&self, status: u16, body: &serde_json::Value, authenticated: bool) -> RemoteReply {
    let text = serde_json::json!({
        "epoch": self.epoch,
        "revision": self.revision,
        "body": body,
    });
    RemoteReply {
        status,
        body: text.to_string().into_bytes(),
        authenticated,
    }
}

fn error_json(&self, code: &str, message: &str) -> Vec<u8> {
    serde_json::json!({
        "epoch": self.epoch,
        "revision": self.revision,
        "error": { "code": code, "message": message },
    })
    .to_string()
    .into_bytes()
}

/// A refusal, logged by method, path and code only.
fn refuse(
    &self,
    request: &RemoteRequest,
    status: u16,
    code: &str,
    message: &str,
    authenticated: bool,
) -> RemoteReply {
    log::info!(
        "remote: {} {} refused: {code}",
        request.method,
        request.path
    );
    RemoteReply {
        status,
        body: self.error_json(code, message),
        authenticated,
    }
}

