1	//! The Remote devices dialog: who this host is to a device, where it
2	//! listens, the pairing window with its QR code, and the devices paired
3	//! so far with their scope and a Revoke. Nothing here decides anything:
4	//! every change is an action, and the host's state is read back from
5	//! the core each frame.
6	
7	use egui::{Context, RichText, Ui};
8	
9	use super::{DrawCtx, GAP, cards::since_text, theme};
10	use crate::adapters::remote;
11	use crate::core::{AppAction, AppCore};
12	use crate::ports::remote::Scope;
13	
14	/// What the dialog edits between frames: the name and port fields, the
15	/// scope the next pairing grants, and the QR image for the open code.
16	pub struct RemoteDraft {
17	    pub name: String,
18	    pub port: String,
19	    pub scope: Scope,
20	    /// The QR texture for the code it was made for.
21	    qr: Option<(String, egui::TextureHandle)>,
22	}
23	
24	impl RemoteDraft {
25	    #[must_use]
26	    pub fn open(core: &AppCore) -> Self {
27	        let identity = core.identity();
28	        Self {
29	            name: identity.map(|i| i.server_name.clone()).unwrap_or_default(),
30	            port: identity
31	                .map(|i| i.listen.port.to_string())
32	                .unwrap_or_default(),
33	            scope: Scope::Read,
34	            qr: None,
35	        }
36	    }
37	}
38	
39	/// The dialog's width: the QR and the device rows fit it.
40	const DIALOG_WIDTH: f32 = 620.0;
41	/// Pixels per QR module; the quiet zone is the standard four.
42	const QR_SCALE: usize = 4;
43	const QR_QUIET: usize = 4;
44	
45	pub fn show(cx: &mut DrawCtx<'_>, ctx: &Context) {
46	    let Some(mut draft) = cx.state.remote_dialog.take() else {
47	        return;
48	    };
49	    let mut keep = true;
50	    egui::Window::new("")
51	        .id(egui::Id::new("remote-devices"))
52	        .title_bar(false)
53	        .collapsible(false)
54	        .resizable(true)
55	        .default_width(DIALOG_WIDTH)
56	        .anchor(egui::Align2::CENTER_CENTER, egui::vec2(0.0, 0.0))
57	        .show(ctx, |ui| {
58	            let screen = ctx.content_rect().width();
59	            ui.set_max_width((screen - 80.0).clamp(320.0, DIALOG_WIDTH));
60	            ui.spacing_mut().item_spacing = egui::vec2(GAP, GAP);
61	            ui.label(RichText::new("Remote devices").text_style(theme::brand()));
62	            ui.add_space(8.0);
63	            host(cx, ui, &mut draft);
64	            ui.add_space(8.0);
65	            pairing(cx, ui, &mut draft);
66	            ui.add_space(8.0);
67	            devices(cx, ui);
68	            ui.add_space(8.0);
69	            let p = theme::palette(ui);
70	            ui.label(
71	                RichText::new(
72	                    "What a device reads is redacted: the values of a project's secret variables and of its granted sets are replaced by their names. A secret pasted into a prompt, or printed by a tool, that Switchboard never held is not found.",
73	                )
74	                .small()
75	                .color(p.n600),
76	            );
77	            ui.horizontal(|ui| {
78	                if theme::ghost_muted(ui, "Close").clicked() {
79	                    keep = false;
80	                }
81	            });
82	        });
83	    if keep {
84	        cx.state.remote_dialog = Some(draft);
85	    }
86	}
87	
88	/// This host: its name, id and key, and where it listens.
89	fn host(cx: &mut DrawCtx<'_>, ui: &mut Ui, draft: &mut RemoteDraft) {
90	    theme::section(ui, "This Mac");
91	    let Some(identity) = cx.core.identity().cloned() else {
92	        ui.label("The host has no identity yet; see the log.");
93	        return;
94	    };
95	    ui.horizontal(|ui| {
96	        let id = ui.label("Name").id;
97	        let field = ui
98	            .add(egui::TextEdit::singleline(&mut draft.name).desired_width(240.0))
99	            .labelled_by(id);
100	        if field.lost_focus() && draft.name.trim() != identity.server_name {
101	            cx.dispatch(AppAction::SetServerName(draft.name.clone()));
102	        }
103	    });
104	    ui.label(theme::meta_text(ui, format!("Id {}", identity.server_id)));
105	    ui.label(theme::meta_text(
106	        ui,
107	        format!("Key {}", short_hash(&identity.spki_sha256)),
108	    ));
109	    ui.horizontal(|ui| {
110	        let mut lan = identity.listen.lan;
111	        if ui
112	            .checkbox(&mut lan, "Allow devices on the local network")
113	            .on_hover_text("Off, the port answers this Mac alone; on, it listens on every interface and only paired devices get past /info")
114	            .changed()
115	        {
116	            cx.dispatch(AppAction::SetRemoteListen {
117	                lan,
118	                port: identity.listen.port,
119	            });
120	        }
121	        let id = ui.label("Port").id;
122	        let field = ui
123	            .add(egui::TextEdit::singleline(&mut draft.port).desired_width(64.0))
124	            .labelled_by(id);
125	        if field.lost_focus() {
126	            match draft.port.trim().parse::<u16>() {
127	                Ok(port) if port != 0 && port != identity.listen.port => {
128	                    cx.dispatch(AppAction::SetRemoteListen {
129	                        lan: identity.listen.lan,
130	                        port,
131	                    });
132	                }
133	                Ok(_) => {}
134	                Err(_) => draft.port = identity.listen.port.to_string(),
135	            }
136	        }
137	    });
138	}
139	
140	/// The pairing window: open it with a scope, or show the code it holds.
141	fn pairing(cx: &mut DrawCtx<'_>, ui: &mut Ui, draft: &mut RemoteDraft) {
142	    theme::section(ui, "Pairing");
143	    let p = theme::palette(ui);
144	    if cx.core.identity_rotated() {
145	        ui.label(
146	            RichText::new(
147	                "The host's key was remade at this launch, so every earlier pairing is invalid. Pair each device again.",
148	            )
149	            .color(p.accent_2_text),
150	        );
151	    }
152	    let Some(identity) = cx.core.identity().cloned() else {
153	        return;
154	    };
155	    if let Some(window) = cx.core.pairing().cloned() {
156	        let port = cx.remote_port.unwrap_or(identity.listen.port);
157	        let address = remote::local_address()
158	            .map(|ip| format!("{ip}:{port}"))
159	            .unwrap_or_default();
160	        let payload = serde_json::json!({
161	            "server_id": identity.server_id,
162	            "spki_sha256": identity.spki_sha256,
163	            "code": window.code,
164	            "addresses": if address.is_empty() { Vec::new() } else { vec![address.clone()] },
165	        })
166	        .to_string();
167	        if draft
168	            .qr
169	            .as_ref()
170	            .is_none_or(|(code, _)| *code != window.code)
171	        {
172	            draft.qr = qr_texture(ui.ctx(), &payload).map(|t| (window.code.clone(), t));
173	        }
174	        ui.horizontal(|ui| {
175	            if let Some((_, texture)) = &draft.qr {
176	                ui.image(egui::load::SizedTexture::from_handle(texture));
177	            }
178	            ui.vertical(|ui| {
179	                ui.label(
180	                    RichText::new(spaced(&window.code))
181	                        .text_style(theme::h1())
182	                        .family(egui::FontFamily::Monospace),
183	                );
184	                ui.label(theme::meta_text(
185	                    ui,
186	                    format!("Key {}", short_hash(&identity.spki_sha256)),
